import{_ as o,c as e,o as d,ag as r}from"./chunks/framework._xRlcm3f.js";const h=JSON.parse('{"title":"GitLab Astro 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/gitlab-gitlabastro.md","filePath":"platforms/gitlab-gitlabastro.md","lastUpdated":1790228279000}'),a={name:"platforms/gitlab-gitlabastro.md"};function c(s,t,i,l,n,g){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="gitlab-astro-配置指南" tabindex="-1">GitLab Astro 配置指南 <a class="header-anchor" href="#gitlab-astro-配置指南" aria-label="Permalink to &quot;GitLab Astro 配置指南&quot;">​</a></h1><p>通过 <strong>GitLab API</strong> 将文章发布到 GitLab 上的 <strong>Astro</strong> 站点仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Astro 站点的 <strong>GitLab 仓库</strong>（如 <code>astro-blog</code>，博客文章放在 <code>src/content/blog</code> 下）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitLab 个人访问令牌（Personal Access Token）</strong>（GitLab 右上角头像 → Preferences → Access Tokens，或访问 <code>/-/user_settings/personal_access_tokens</code>，勾选 <code>api</code> 或 <code>write_repository</code> 范围）。</li><li>站点仓库已配置构建部署（例如 GitLab CI / Pages / Vercel / Netlify），推送 <code>.md</code> 后能触发重新构建上线。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>你的 GitLab 实例地址（自建实例填自己的域名，如 <code>https://gitlab.example.com</code>），用于拼出仓库地址</td></tr><tr><td>API 地址</td><td>GitLab API 地址，<strong>与平台首页一致</strong>；填写平台首页后会自动同步为该地址，平台首页留空时该地址也会被清空</td></tr><tr><td>用户名</td><td>GitLab 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitLab 个人访问令牌（Personal Access Token），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>站点仓库名（裸仓库名，不带 <code>owner/</code> 前缀），例如 <code>astro-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code></td></tr><tr><td>存储目录</td><td>文章存储目录，默认 <code>src/content/blog</code>（Astro 内容集合目录）。发布后的 <code>.md</code> 会写入该目录</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[slug].md</code>（文章别名），与 Astro 内容集合的文件路径约定一致</td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code>。Astro 内容集合按文件路径生成路由，实际站点地址由文件路径决定，此规则仅作查看参考</td></tr><tr><td>预览规则</td><td>GitLab blob 预览规则，固定 <code>/[user]/[repo]/blob/[branch]/[docpath]</code>，查看链接即该 <code>.md</code> 在仓库中的地址，<strong>不支持修改</strong></td></tr><tr><td>发布目录</td><td>默认 <code>src/content/blog</code>。该平台<strong>不支持修改发布目录</strong>（配置页为只读提示），如需更换请删除账号后重新发布</td></tr><tr><td>YAML 永久链接</td><td><strong>不提供该开关</strong>：Astro 的路由由内容集合的文件路径决定，不识别 Front Matter 中的链接字段</td></tr><tr><td>图床</td><td>默认「当前平台」：图片提交到仓库 <code>public/images</code>，文章引用<strong>绝对路径</strong> <code>/images/&lt;图片名&gt;</code></td></tr></tbody></table><p>发布写入的 Front Matter 含 <code>title</code>、<code>description</code>、<code>pubDate</code>（<code>yyyy-MM-dd</code>）、<code>tags</code>、<code>categories</code>、<code>keywords</code>（可在「YAML 预设配置」中覆盖）。</p><p>「YAML 预设配置」<strong>留空时不追加额外字段</strong>，发布时只把该项里的键逐键合并进 Front Matter。</p><h2 id="三、图片约定-astro-公共资源目录" tabindex="-1">三、图片约定（Astro 公共资源目录） <a class="header-anchor" href="#三、图片约定-astro-公共资源目录" aria-label="Permalink to &quot;三、图片约定（Astro 公共资源目录）&quot;">​</a></h2><ul><li>Astro 把 <code>public/</code> 下的资源<strong>原样拷贝</strong>到构建输出根目录，因此图片放 <code>public/images</code>，站点上即以 <code>/images/&lt;图片名&gt;</code> 访问。</li><li><code>imageStorePath = public/images</code> 是<strong>仓库根目录</strong>下的固定路径（不随文章目录变化）。</li><li><code>imageLinkPath = /images</code> 生成<strong>绝对路径</strong>引用 <code>/images/&lt;图片名&gt;</code>（绝对路径，不是相对资源的 <code>./images</code>）。</li><li>发布带图文章后，仓库中会出现 <code>.md</code> 与 <code>public/images/&lt;图片名&gt;</code>。</li></ul><h2 id="四、发布目录的限制" tabindex="-1">四、发布目录的限制 <a class="header-anchor" href="#四、发布目录的限制" aria-label="Permalink to &quot;四、发布目录的限制&quot;">​</a></h2><p>Astro 的发布目录固定为内容集合目录（默认 <code>src/content/blog</code>），<strong>配置页不提供修改</strong>（「发布目录」为只读提示）。如需更换位置，请删除账号后重新发布。</p><h2 id="五、验证与发布" tabindex="-1">五、验证与发布 <a class="header-anchor" href="#五、验证与发布" aria-label="Permalink to &quot;五、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 令牌、仓库、分支校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 GitLab Astro → 发布。文章 <code>.md</code> 提交到 <code>src/content/blog/[slug].md</code>。</li><li>「查看文章」打开仓库 blob 地址；站点线上地址由内容集合的文件路径决定，需站点已构建部署。</li><li>带图发布时图片提交到 <code>public/images</code>，文章引用 <code>/images/&lt;图片名&gt;</code>。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认个人访问令牌对目标仓库有 push 权限（<code>api</code> 或 <code>write_repository</code> 范围），仓库名与分支填写正确。权限不足会收到 401/403。</li><li><strong>自建 GitLab 该怎么填平台首页</strong>：平台首页填你的实例地址（如 <code>https://gitlab.example.com</code>），API 地址会同步为该地址；令牌地址同样由实例地址拼出（<code>/-/user_settings/personal_access_tokens</code>），需在你自己实例的偏好设置里生成令牌。</li><li><strong>图片要怎么发布</strong>：图床默认「当前平台」，图片提交到仓库 <code>public/images</code>，文章引用绝对路径 <code>/images/&lt;图片名&gt;</code>；Astro 构建时把 <code>public/</code> 下的资源原样拷贝到输出根目录。</li><li><strong>查看链接打不开</strong>：查看链接为仓库中该 <code>.md</code> 的 blob 地址（<code>/[user]/[repo]/blob/[branch]/[docpath]</code>），仓库中存在该文件即可打开，需已登录 GitLab 且对该仓库有访问权限；该规则固定，不支持修改。</li><li><strong>发布目录能不能改</strong>：不能，固定为内容集合目录（默认 <code>src/content/blog</code>）；如需更换请删除账号后重新发布。</li><li><strong>有没有「YAML 永久链接」开关</strong>：没有。Astro 的路由由内容集合的文件路径决定，不识别 Front Matter 中的链接字段，因此配置页不提供该开关。</li><li><strong>线上没有新文章</strong>：Astro 站点需要构建。确认仓库已绑定 GitLab CI / Pages / Vercel 等自动构建；仅推送 <code>.md</code> 不会直接改变已部署站点。</li><li><strong>更新与删除</strong>：点「更新」会重新提交该文章并产生一次新提交；「删除」会移除仓库中对应的 <code>.md</code>，站点需重新构建才会同步下线。</li></ul>',16)])])}const p=o(a,[["render",c]]);export{h as __pageData,p as default};
